CREATE TABLE IF NOT EXISTS asset_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_identifier text UNIQUE NOT NULL, submitted_by text, contributor_type text NOT NULL DEFAULT 'community', name text NOT NULL, asset_type_code text NOT NULL, description text, jurisdiction_code text, location_text text, latitude numeric(10,7), longitude numeric(10,7), rights_holder_name text, rights_basis text, status text NOT NULL DEFAULT 'submitted', review_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());